const API_URL = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000";

function safeFileName(name: string) {
  const base = name
    .replace(/[^\p{L}\p{N}\- ]+/gu, "")
    .replace(/\s+/g, " ")
    .trim();
  return `${base || "boq"}.xlsx`;
}

/** Downloads the BOQ as an Excel file generated by the API. */
export async function downloadBoqExcel(boqId: string, boqName: string) {
  const res = await fetch(`${API_URL}/boqs/${boqId}/export`, {
    credentials: "include",
  });
  if (!res.ok) {
    const err = await res.json().catch(() => null);
    const detail =
      typeof err?.detail === "string" ? err.detail : `status ${res.status}`;
    throw new Error(`Export failed: ${detail}`);
  }

  const blob = await res.blob();
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = safeFileName(boqName);
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}
